from pathlib import Path

import yaml

from resilens.config.config import CONFIGS_DIR
from resilens.config.schema import AnalyzerConfig, ModeConfig, ProfileConfig, RunConfig

ANALYZER_CONFIG = CONFIGS_DIR / "analyzer" / "thresholds.yaml"


def load_analyzer_config(path: Path = ANALYZER_CONFIG) -> AnalyzerConfig:
    """Load Degradation Analyzer thresholds (generated by benchmarks/degradation/calibrate.py)."""
    return AnalyzerConfig(**yaml.safe_load(Path(path).read_text(encoding="utf-8")))


